import os
import boto3

log_group_name = os.getenv('LOG_GROUP_NAME')
log_stream_name = os.getenv('LOG_STREAM_NAME')

def create_log_client():
    return boto3.client('logs')

def create_log_group():
    client = create_log_client()
    client.create_log_group(logGroupName=log_group_name)

def create_log_stream():
    client = create_log_client()
    client.create_log_stream(logGroupName=log_group_name, logStreamName=log_stream_name)

class LogRequest:
    def __init__(self, log_group_name, log_stream_name, log_events):
        self.log_group_name = log_group_name
        self.log_stream_name = log_stream_name
        self.log_events = log_events

class LogResponse:
    def __init__(self, events):
        self.events = events

class LogNormalizer:
    @staticmethod
    def normalize(log_event):
        return {
            'timestamp': log_event['timestamp'],
            'message': json.dumps(log_event['message'])
        }

import re

def check_log_text_safety(log_text):
    unsafe_patterns = [
        r'password',
        r'secret',
        r'token'
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, log_text, re.IGNORECASE):
            return False
    return True

log_text = 'User logged in with password 12345'
print(check_log_text_safety(log_text))
